-- Deterministic UI inspection states, generated by real story actions.
-- Used only by preview/test tooling, never the playable route.
local Prologue=require('game.PrologueState')
local Chapter1=require('preview.Chapter1Fixtures')
local Fixtures={}
Fixtures.names={'锁屏','群聊','发送失败','饭团','瓶盖','关东煮'}
for _,name in ipairs(Chapter1.names) do Fixtures.names[#Fixtures.names+1]=name end
function Fixtures.make(index)
    if index>6 then return Chapter1.make(index-6) end
    local story=Prologue.new({random=function()return .37 end})
    local function step(seconds) for _=1,math.floor(seconds/.05+.5) do story:update(.05,{camYaw=0,moving=false});story:drainEvents() end end
    step(20)
    if index==1 then story:openPhone('lock');step(1)
    elseif index==2 or index==3 then
        story:openPhone('chat');story:onPhone('pick:0')
        if index==3 then step(112) end
        story:onPhone('send');step(2)
    elseif index==4 then story:startBrowse('shelf');step(4)
    elseif index==5 then story:startBrowse('fridge');step(4);story:onBrowse('choice:0');step(5)
    else story:startBrowse('food');step(4);story:onBrowse('choice:0');step(3);story:onBrowse('choice:0');step(4) end
    return story
end
return Fixtures
